const assert = require('node:assert/strict');
const fs = require('node:fs');
const {chromium} = require('playwright');
const {createHash} = require('node:crypto');

(async () => {
    const output = __dirname + '/docs-selection-merged-review';
    fs.mkdirSync(output,{recursive:true});
    const browser = await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
    const pages = [
        ['readme','Understand the production build'],
        ['maintaining','reference-parity'],
        ['archived/image-baselines','Original tutorial images'],
        ['journey/contents','1,321 active runnable checkpoints'],
        ['journey/03a-mathematics','Kernel motion values'],
        ['journey/stage-gap','Eight of 46'],
        ['journey/consolidation/42-window','A bounded integer picking pass'],
        ['journey/42a-id','Keep exact object IDs'],
        ['journey/12-identity','One camera for drawing and picking'],
        ['journey/consolidation/34g-heartbeat','Current startup and early fetching'],
        ['journey/consolidation/96zzzzzq-prepare-one-shared-render-origin','Current GPU completion pacing'],
        ['journey/13a-history','single runnable subject'],
        ['journey/16-orbit','single runnable subject'],
        ['journey/consolidation/15-perspective','single runnable subject'],
        ['archived/journey-consolidation-13a-history','Retain reversible scene snapshots'],
    ];
    const errors = [], records = [], checkedSources = new Set();
    try {
        const page = await browser.newPage({viewport:{width:1280,height:800}});
        page.on('pageerror',error => errors.push(error.message));
        for (const [slug,wanted] of pages) {
            await page.goto('http://127.0.0.1:8798/docs/#/course/'+slug);
            await page.waitForFunction(text => document.querySelector('article.doc')?.textContent.includes(text),wanted);
            const article = page.locator('article.doc');
            assert(!(await article.innerText()).includes('--8<--'));
            if (slug === 'journey/03a-mathematics') {
                const text = await article.innerText();
                for (const operation of ['Vector::lerp','Color::lerp','Line::lerp','Polyline::resampled','Polyline::morph','Xform::interpolate']) assert(text.includes(operation),operation);
                assert(text.includes('Both inputs are resampled'));
                assert(text.includes('does not preserve vector length'));
                assert(text.includes('with reversed endpoints'));
                await article.getByRole('heading',{name:'Kernel motion values',exact:true}).scrollIntoViewIfNeeded();
                await page.screenshot({path:output+'/kernel-motion-desktop.png'});
            }
            const receipts = await article.locator('a').evaluateAll(links => links.filter(a => /\.json(?:[?#]|$)/.test(a.href)).map(a => a.href));
            for (const receipt of new Set(receipts)) { const response=await page.request.get(receipt); assert(response.ok(),receipt); JSON.parse(await response.text()); }
            if (slug === 'archived/image-baselines') {
                for (const [label,hash] of [['The historical triangle image','4c76ae64c7cc26384b9e951569e7b551ecd6d49843b3b5f6dd7e1d5d8400cfcc'],['direct dock image','4c76ae64c7cc26384b9e951569e7b551ecd6d49843b3b5f6dd7e1d5d8400cfcc'],['archive copy','4c76ae64c7cc26384b9e951569e7b551ecd6d49843b3b5f6dd7e1d5d8400cfcc'],['versioned handoff native image','748521c6fd282f48b091b404e6c27562a92e4df33253b5c6327161ec1a4bcfb1']]) {
                    const address = await article.getByRole('link',{name:label,exact:true}).getAttribute('href');
                    const response = await page.request.get(new URL(address,page.url()).href); assert(response.ok());
                    assert.equal(createHash('sha256').update(await response.body()).digest('hex'),hash,label);
                }
            }
            const images = article.locator('img');
            for (let i=0;i<await images.count();i++) {
                await images.nth(i).scrollIntoViewIfNeeded();
                await images.nth(i).evaluate(image => image.decode());
                assert(await images.nth(i).evaluate(image => image.naturalWidth > 0));
            }
            const sources = await article.locator('a').evaluateAll(links => links.filter(a => /\.(rs|wgsl)(?:\.txt)?(?:[?#]|$)/.test(a.href)).map(a => a.href));
            for (const source of new Set(sources)) {
                if (checkedSources.has(source)) continue;
                if (source.startsWith('https://github.com/')) await new Promise(resolve=>setTimeout(resolve,5000));
                let response;
                for (let attempt=0;attempt<3;attempt++) {
                    response=await page.request.get(source);
                    if (response.ok()) break;
                    console.log('Source HTTP '+response.status()+' '+source+' attempt '+(attempt+1));
                    if (![403,429,500,502,503,504].includes(response.status())) break;
                    await new Promise(resolve=>setTimeout(resolve,20000*(attempt+1)));
                }
                assert(response.ok(),source+' HTTP '+response.status());
                checkedSources.add(source);
            }
            records.push({slug,heading:await article.locator('h1').innerText(),images:await images.count(),sources:sources.length});
            console.log('Reviewed '+slug);
        }
        await page.goto('http://127.0.0.1:8798/docs/#/course/journey/12-identity');
        await page.waitForFunction(() => document.querySelector('article.doc')?.textContent.includes('One camera for drawing and picking'));
        await page.screenshot({path:output+'/selection-desktop.png'});
        await page.setViewportSize({width:390,height:844});
        await page.goto('http://127.0.0.1:8798/docs/#/course/journey/consolidation/96zzzzzq-prepare-one-shared-render-origin');
        await page.waitForFunction(() => document.querySelector('article.doc')?.textContent.includes('Current GPU completion pacing'));
        await page.getByRole('button',{name:'Menu',exact:true}).click();
        await page.waitForFunction(() => document.querySelector('#site-nav')?.classList.contains('open'));
        await page.keyboard.press('Escape');
        await page.waitForFunction(() => document.querySelector('#site-nav')?.getBoundingClientRect().right <= 1);
        await page.screenshot({path:output+'/pacing-upright.png'});
        assert.deepEqual(errors,[]);
        fs.writeFileSync(output+'/result.json',JSON.stringify({status:'passed',browser:browser.version(),records,errors},null,2)+'\n');
    } finally { await browser.close(); }
})().catch(error => {console.error(error);process.exitCode=1;});
